    // langCompat reports an error if the representation of a numeric
    // literal is not compatible with the current language version.
    void rec::langCompat(Checker* check, ast::BasicLit* lit)
    {
        auto s = lit->Value;
        if(len(s) <= 2 || rec::allowVersion(gocpp::recv(check), go1_13))
        {
            return;
        }
        // len(s) > 2
        if(strings::Contains(s, "_"_s))
        {
            rec::versionErrorf(gocpp::recv(check), lit, go1_13, "underscore in numeric literal"_s);
            return;
        }
        if(s[0] != '0')
        {
            return;
        }
        auto radix = s[1];
        if(radix == 'b' || radix == 'B')
        {
            rec::versionErrorf(gocpp::recv(check), lit, go1_13, "binary literal"_s);
            return;
        }
        if(radix == 'o' || radix == 'O')
        {
            rec::versionErrorf(gocpp::recv(check), lit, go1_13, "0o/0O-style octal literal"_s);
            return;
        }
        if(lit->Kind != token::INT && (radix == 'x' || radix == 'X'))
        {
            rec::versionErrorf(gocpp::recv(check), lit, go1_13, "hexadecimal floating-point literal"_s);
        }
    }

